<script setup lang="ts">
import { computed, ref } from 'vue'
import { backendClient } from '../api/backend-client'
import { backendDemo } from '../lib/backend-demo'
import type { ActionTaskView } from '../api/backend-types'
defineProps<{ today?: boolean }>()
const plan=computed(()=>backendDemo.state.liveAction),busy=ref(false),saving=ref(''),error=ref('')
async function load(){if(busy.value||saving.value)return;busy.value=true;error.value='';try{const result=await backendClient.action();if(!result||!Array.isArray(result.phases))throw new Error('Incomplete plan');backendDemo.setAction(result)}catch{error.value='暂时没有取得最新计划，当前内容仍保留。请重试。'}finally{busy.value=false}}
async function done(task: ActionTaskView){if(saving.value)return;saving.value=task.task_id;error.value='';try{const result=await backendClient.actionDone({task_id:task.task_id,done:!task.done});if(!result||!Array.isArray(result.phases))throw new Error('Incomplete plan');backendDemo.setAction(result)}catch{error.value='任务状态没有保存成功，请重试。原状态仍保留。'}finally{saving.value=''}}
</script>
<template><section class="live-action"><div class="ws-section-head"><h2>{{ today?'当前行动':'阶段任务' }}</h2><button class="btn" :disabled="busy||!!saving" @click="load">{{ busy?'正在读取…':'读取最新行动计划' }}</button></div><p v-if="error" class="ws-field-error" role="alert">{{ error }}</p><template v-if="plan"><section v-if="today&&plan.next_task" class="report-lead"><h3>{{ plan.next_task.text }}</h3><p>{{ plan.next_task.phase }}</p><p v-if="plan.next_task.due_date" class="ws-muted">计划日期：{{ plan.next_task.due_date }}</p><button class="btn btn--primary" :disabled="!!saving" @click="done(plan.next_task)">{{ saving===plan.next_task.task_id?'正在保存…':plan.next_task.done?'恢复任务':'标记完成' }}</button></section><details v-for="(phase,i) in plan.phases" :key="phase.name" class="plan-stage" :open="!today&&i===0"><summary><span><strong>{{ phase.name }}</strong><small>{{ phase.date_range }} · {{ phase.tasks?.filter(t=>t.done).length ?? 0 }} / {{ phase.tasks?.length ?? 0 }} 件已完成</small></span></summary><ul class="ws-mini-list"><li v-for="task in phase.tasks?.filter(t=>!today||t.task_id!==plan?.next_task?.task_id)" :key="task.task_id" class="live-task"><div><strong>{{ task.text }}</strong><p v-if="task.due_date" class="ws-muted">{{ task.due_date }}</p><p v-if="task.done_at" class="ws-muted">完成于 {{ new Date(task.done_at).toLocaleString('zh-CN') }}</p></div><button class="btn" :aria-pressed="!!task.done" :disabled="!!saving" @click="done(task)">{{ saving===task.task_id?'正在保存…':task.done?'恢复任务':'完成任务' }}</button></li></ul><p v-if="!phase.tasks?.length" class="ws-muted">当前阶段尚未安排任务。</p></details><p v-if="!plan.phases?.length" class="ws-empty">当前尚未形成阶段计划，可以在咨询中明确方向。</p><p class="ws-muted ws-section">以上按本次读取的计划与任务回包显示；不与预置任务混算。</p></template></section></template>
